import{_ as e,o as t,c as r,a2 as i}from"./chunks/framework.C0KMm31j.js";const o="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_13_value_to_policy.png",h="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_13_log_derivative.png",l="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_13_reinforce_loop.png",n="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_13_baseline_advantage.png",s="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_13_continuous_safety.png",f=JSON.parse('{"title":"不再从 Q 值里挑动作：策略梯度怎样直接学会决策","description":"DQN（深度 Q 网络）的决策方式是先估计每个离散动作的价值，再选择最大值。Policy Gradient（策略梯度）换了一条路线：直接用参数化策略 \\\\(\\\\pi\\\\theta(a|s)\\\\) 表示动作分布，并沿着期望回报上升的方向修改参数。离散动作可以输出分类分布，连续动作可以输出高斯分布等概率模型，不","frontmatter":{"title":"不再从 Q 值里挑动作：策略梯度怎样直接学会决策","description":"DQN（深度 Q 网络）的决策方式是先估计每个离散动作的价值，再选择最大值。Policy Gradient（策略梯度）换了一条路线：直接用参数化策略 \\\\(\\\\pi\\\\theta(a|s)\\\\) 表示动作分布，并沿着期望回报上升的方向修改参数。离散动作可以输出分类分布，连续动作可以输出高斯分布等概率模型，不","date":"2026-08-13","topic":"强化学习","section":"强化学习分类系列","readingTime":12,"source":"2026-08-13/rl_series_13_policy_gradient_reinforce.md","status":"published","cover":"/article-assets/2026-08-13/rl_series_13_value_to_policy.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/rl/rl-series-13-policy-gradient-reinforce"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"不再从 Q 值里挑动作：策略梯度怎样直接学会决策"}],["meta",{"property":"og:description","content":"DQN（深度 Q 网络）的决策方式是先估计每个离散动作的价值，再选择最大值。Policy Gradient（策略梯度）换了一条路线：直接用参数化策略 \\\\(\\\\pi\\\\theta(a|s)\\\\) 表示动作分布，并沿着期望回报上升的方向修改参数。离散动作可以输出分类分布，连续动作可以输出高斯分布等概率模型，不"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/rl/rl-series-13-policy-gradient-reinforce"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_13_value_to_policy.png"}],["meta",{"property":"article:published_time","content":"2026-08-13"}],["meta",{"name":"twitter:title","content":"不再从 Q 值里挑动作：策略梯度怎样直接学会决策"}],["meta",{"name":"twitter:description","content":"DQN（深度 Q 网络）的决策方式是先估计每个离散动作的价值，再选择最大值。Policy Gradient（策略梯度）换了一条路线：直接用参数化策略 \\\\(\\\\pi\\\\theta(a|s)\\\\) 表示动作分布，并沿着期望回报上升的方向修改参数。离散动作可以输出分类分布，连续动作可以输出高斯分布等概率模型，不"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_13_value_to_policy.png"}]],"prev":{"text":"DQN 仍会高估、浪费样本、探索低效：进阶改造到底改了哪里","link":"/rl/rl-series-12-dqn-advanced"},"next":{"text":"演员负责行动，评论家负责打分：Actor-Critic 为什么能边走边学","link":"/rl/rl-series-14-actor-critic"}},"headers":[],"relativePath":"rl/rl-series-13-policy-gradient-reinforce.md","filePath":"rl/rl-series-13-policy-gradient-reinforce.md","lastUpdated":null}'),d={name:"rl/rl-series-13-policy-gradient-reinforce.md"};function c(p,a,_,u,b,q){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="不再从-q-值里挑动作-策略梯度怎样直接学会决策" tabindex="-1">不再从 Q 值里挑动作：策略梯度怎样直接学会决策 <a class="header-anchor" href="#不再从-q-值里挑动作-策略梯度怎样直接学会决策" aria-label="Permalink to &quot;不再从 Q 值里挑动作：策略梯度怎样直接学会决策&quot;">​</a></h1><p>DQN（深度 Q 网络）的决策方式是先估计每个离散动作的价值，再选择最大值。Policy Gradient（策略梯度）换了一条路线：直接用参数化策略 (\\pi_\\theta(a|s)) 表示动作分布，并沿着期望回报上升的方向修改参数。离散动作可以输出分类分布，连续动作可以输出高斯分布等概率模型，不再要求逐个穷举动作求最大值。</p><p>直接优化策略并不意味着训练更简单。策略采取的动作是随机样本，环境通常不可微，单条轨迹回报的方差很大，参数一更新，旧数据对应的策略分布也随之过时。REINFORCE（蒙特卡洛策略梯度）提供了最干净的数学起点：奖励不需要可微，只要能够采样轨迹、计算动作对数概率和回报，就能估计策略梯度。</p><h2 id="一、先给出整篇文章的结论" tabindex="-1">一、先给出整篇文章的结论 <a class="header-anchor" href="#一、先给出整篇文章的结论" aria-label="Permalink to &quot;一、先给出整篇文章的结论&quot;">​</a></h2><h3 id="_1-1-策略网络直接输出动作分布" tabindex="-1">1.1 策略网络直接输出动作分布 <a class="header-anchor" href="#_1-1-策略网络直接输出动作分布" aria-label="Permalink to &quot;1.1 策略网络直接输出动作分布&quot;">​</a></h3><p>DQN 输出动作价值，策略梯度输出 (\\pi_\\theta(a|s))。训练的对象不再是“动作值是否准确”，而是“哪些动作概率应增大或减小”。</p><h3 id="_1-2-对数导数技巧绕开环境求导" tabindex="-1">1.2 对数导数技巧绕开环境求导 <a class="header-anchor" href="#_1-2-对数导数技巧绕开环境求导" aria-label="Permalink to &quot;1.2 对数导数技巧绕开环境求导&quot;">​</a></h3><p>策略梯度只需要对策略的对数概率求导。状态转移和奖励可以来自黑盒仿真器，甚至包含不可微规则，只要交互样本可获得即可。</p><h3 id="_1-3-reinforce-无偏但通常高方差" tabindex="-1">1.3 REINFORCE 无偏但通常高方差 <a class="header-anchor" href="#_1-3-reinforce-无偏但通常高方差" aria-label="Permalink to &quot;1.3 REINFORCE 无偏但通常高方差&quot;">​</a></h3><p>完整回报包含真实后续奖励，不依赖价值自举；随机动作、随机环境和长时域奖励会让梯度估计剧烈波动，样本效率通常较低。</p><h3 id="_1-4-连续动作可表示不等于可安全控制" tabindex="-1">1.4 连续动作可表示不等于可安全控制 <a class="header-anchor" href="#_1-4-连续动作可表示不等于可安全控制" aria-label="Permalink to &quot;1.4 连续动作可表示不等于可安全控制&quot;">​</a></h3><p>高斯策略可以输出连续转角或加速度，但动作边界、分布参数化、动力学可行性和独立安全约束仍需专门设计。</p><p><img src="'+o+'" alt="从动作价值选择转向直接优化策略分布"></p><h2 id="二、为什么要直接学习策略" tabindex="-1">二、为什么要直接学习策略 <a class="header-anchor" href="#二、为什么要直接学习策略" aria-label="Permalink to &quot;二、为什么要直接学习策略&quot;">​</a></h2><h3 id="_2-1-动作最大化在连续空间很困难" tabindex="-1">2.1 动作最大化在连续空间很困难 <a class="header-anchor" href="#_2-1-动作最大化在连续空间很困难" aria-label="Permalink to &quot;2.1 动作最大化在连续空间很困难&quot;">​</a></h3><p>价值方法需要计算 (\\arg\\max_a Q(s,a))。离散动作可以遍历，连续动作却需要在每个控制周期求解优化问题，既昂贵又可能落入局部最优。</p><h3 id="_2-2-随机策略天然携带探索" tabindex="-1">2.2 随机策略天然携带探索 <a class="header-anchor" href="#_2-2-随机策略天然携带探索" aria-label="Permalink to &quot;2.2 随机策略天然携带探索&quot;">​</a></h3><p>策略输出概率分布后，智能体按分布采样动作。探索不再必须额外套一层 ε-贪心，策略的不确定性本身就决定尝试范围。</p><h3 id="_2-3-多峰动作仍可能需要复杂分布" tabindex="-1">2.3 多峰动作仍可能需要复杂分布 <a class="header-anchor" href="#_2-3-多峰动作仍可能需要复杂分布" aria-label="Permalink to &quot;2.3 多峰动作仍可能需要复杂分布&quot;">​</a></h3><p>同一驾驶状态下，让行和先行可能都是合理模式。单峰高斯只能表达一个中心和尺度，直接学习策略不代表自动具备多模态表达能力。</p><h2 id="三、策略网络输出什么" tabindex="-1">三、策略网络输出什么 <a class="header-anchor" href="#三、策略网络输出什么" aria-label="Permalink to &quot;三、策略网络输出什么&quot;">​</a></h2><h3 id="_3-1-离散动作使用分类分布" tabindex="-1">3.1 离散动作使用分类分布 <a class="header-anchor" href="#_3-1-离散动作使用分类分布" aria-label="Permalink to &quot;3.1 离散动作使用分类分布&quot;">​</a></h3><p>网络输出 Logit（未归一化对数概率），经 Softmax（归一化指数函数）得到动作概率。所有概率非负且和为一。</p><h3 id="_3-2-连续动作常用高斯分布" tabindex="-1">3.2 连续动作常用高斯分布 <a class="header-anchor" href="#_3-2-连续动作常用高斯分布" aria-label="Permalink to &quot;3.2 连续动作常用高斯分布&quot;">​</a></h3><p>网络可输出均值 (\\mu_\\theta(s)) 和标准差 (\\sigma_\\theta(s))，再采样：</p><p>$$ A_t\\sim\\mathcal N\\left(\\mu_\\theta(S_t),\\sigma_\\theta^2(S_t)\\right) $$</p><p>标准差必须为正，常通过输出对数标准差再指数化实现。</p><h3 id="_3-3-动作边界需要显式变换" tabindex="-1">3.3 动作边界需要显式变换 <a class="header-anchor" href="#_3-3-动作边界需要显式变换" aria-label="Permalink to &quot;3.3 动作边界需要显式变换&quot;">​</a></h3><p>方向盘和加速度具有有限范围。直接裁剪高斯样本会改变实际分布，却仍用未裁剪分布计算对数概率；更严谨的做法是使用 Tanh（双曲正切）压缩并处理概率变换，或选择有界分布。</p><h2 id="四、优化目标到底是什么" tabindex="-1">四、优化目标到底是什么 <a class="header-anchor" href="#四、优化目标到底是什么" aria-label="Permalink to &quot;四、优化目标到底是什么&quot;">​</a></h2><h3 id="_4-1-一条轨迹包含完整交互" tabindex="-1">4.1 一条轨迹包含完整交互 <a class="header-anchor" href="#_4-1-一条轨迹包含完整交互" aria-label="Permalink to &quot;4.1 一条轨迹包含完整交互&quot;">​</a></h3><p>轨迹记为 (\\tau=(S_0,A_0,R_1,S_1,\\ldots))。它的概率同时受初始状态、环境转移与策略动作概率影响。</p><h3 id="_4-2-目标是期望折扣回报" tabindex="-1">4.2 目标是期望折扣回报 <a class="header-anchor" href="#_4-2-目标是期望折扣回报" aria-label="Permalink to &quot;4.2 目标是期望折扣回报&quot;">​</a></h3><p>$$ J(\\theta)=\\mathbb E_{\\tau\\sim p_\\theta(\\tau)}[R(\\tau)] $$</p><p>参数不是直接改变奖励函数，而是改变轨迹出现的概率，让高回报轨迹更常发生。</p><h3 id="_4-3-单次高回报不是目标本身" tabindex="-1">4.3 单次高回报不是目标本身 <a class="header-anchor" href="#_4-3-单次高回报不是目标本身" aria-label="Permalink to &quot;4.3 单次高回报不是目标本身&quot;">​</a></h3><p>训练要提高分布意义上的期望，而不是记住偶然成功轨迹。评估也必须使用多回合和多随机种子，报告分布而非最好结果。</p><h2 id="五、环境不可微为什么仍能求梯度" tabindex="-1">五、环境不可微为什么仍能求梯度 <a class="header-anchor" href="#五、环境不可微为什么仍能求梯度" aria-label="Permalink to &quot;五、环境不可微为什么仍能求梯度&quot;">​</a></h2><h3 id="_5-1-使用对数导数恒等式" tabindex="-1">5.1 使用对数导数恒等式 <a class="header-anchor" href="#_5-1-使用对数导数恒等式" aria-label="Permalink to &quot;5.1 使用对数导数恒等式&quot;">​</a></h3><p>对任意正概率 (p_\\theta(\\tau))，有：</p><p>$$ \\nabla_\\theta p_\\theta(\\tau)=p_\\theta(\\tau)\\nabla_\\theta\\log p_\\theta(\\tau) $$</p><h3 id="_5-2-环境项对策略参数的导数为零" tabindex="-1">5.2 环境项对策略参数的导数为零 <a class="header-anchor" href="#_5-2-环境项对策略参数的导数为零" aria-label="Permalink to &quot;5.2 环境项对策略参数的导数为零&quot;">​</a></h3><p>轨迹对数概率可拆为初始状态、策略动作和环境转移之和。假设环境动力学不依赖策略参数 (\\theta)，求导后只剩策略对数概率。</p><h3 id="_5-3-策略梯度成为可采样期望" tabindex="-1">5.3 策略梯度成为可采样期望 <a class="header-anchor" href="#_5-3-策略梯度成为可采样期望" aria-label="Permalink to &quot;5.3 策略梯度成为可采样期望&quot;">​</a></h3><p>$$ \\nabla_\\theta J(\\theta)=\\mathbb E\\left[R(\\tau)\\sum_t\\nabla_\\theta\\log\\pi_\\theta(A_t|S_t)\\right] $$</p><p>无需知道环境转移公式，只需让当前策略采样轨迹并计算网络对数概率。</p><p><img src="'+h+'" alt="对数导数技巧让梯度只穿过策略网络"></p><h2 id="六、概率梯度怎样改变动作倾向" tabindex="-1">六、概率梯度怎样改变动作倾向 <a class="header-anchor" href="#六、概率梯度怎样改变动作倾向" aria-label="Permalink to &quot;六、概率梯度怎样改变动作倾向&quot;">​</a></h2><h3 id="_6-1-正权重提高已采样动作概率" tabindex="-1">6.1 正权重提高已采样动作概率 <a class="header-anchor" href="#_6-1-正权重提高已采样动作概率" aria-label="Permalink to &quot;6.1 正权重提高已采样动作概率&quot;">​</a></h3><p>若某动作对应的回报权重为正，梯度上升会提高 (\\log\\pi_\\theta(a|s))，也就是提高该动作在该状态的概率。</p><h3 id="_6-2-负权重压低已采样动作概率" tabindex="-1">6.2 负权重压低已采样动作概率 <a class="header-anchor" href="#_6-2-负权重压低已采样动作概率" aria-label="Permalink to &quot;6.2 负权重压低已采样动作概率&quot;">​</a></h3><p>若权重为负，更新方向相反。由于动作概率总和固定，某些动作概率上升必然挤压其他动作。</p><h3 id="_6-3-未采样动作没有直接监督" tabindex="-1">6.3 未采样动作没有直接监督 <a class="header-anchor" href="#_6-3-未采样动作没有直接监督" aria-label="Permalink to &quot;6.3 未采样动作没有直接监督&quot;">​</a></h3><p>策略梯度只能使用实际采样的动作。动作从未出现时，它不会获得直接回报证据，却可能因概率归一化被间接改变。</p><h2 id="七、为什么不能把整场总回报给所有动作" tabindex="-1">七、为什么不能把整场总回报给所有动作 <a class="header-anchor" href="#七、为什么不能把整场总回报给所有动作" aria-label="Permalink to &quot;七、为什么不能把整场总回报给所有动作&quot;">​</a></h2><h3 id="_7-1-过去动作不应由更早奖励评分" tabindex="-1">7.1 过去动作不应由更早奖励评分 <a class="header-anchor" href="#_7-1-过去动作不应由更早奖励评分" aria-label="Permalink to &quot;7.1 过去动作不应由更早奖励评分&quot;">​</a></h3><p>时刻 (t) 的动作不会影响已经发生的奖励。使用整场总回报会把动作发生前的奖励也纳入权重，增加无关噪声。</p><h3 id="_7-2-reward-to-go-未来回报-只保留因果后续" tabindex="-1">7.2 Reward-to-Go（未来回报）只保留因果后续 <a class="header-anchor" href="#_7-2-reward-to-go-未来回报-只保留因果后续" aria-label="Permalink to &quot;7.2 Reward-to-Go（未来回报）只保留因果后续&quot;">​</a></h3><p>$$ G_t=\\sum_{k=0}^{T-t-1}\\gamma^kR_{t+k+1} $$</p><p>用 (G_t) 替代整条轨迹回报，不改变期望梯度，却通常降低方差。</p><h3 id="_7-3-折扣改变时间偏好" tabindex="-1">7.3 折扣改变时间偏好 <a class="header-anchor" href="#_7-3-折扣改变时间偏好" aria-label="Permalink to &quot;7.3 折扣改变时间偏好&quot;">​</a></h3><p>(\\gamma) 越小，远期奖励影响越弱。它既是任务目标的一部分，也影响信用传播距离，不能只当作数值稳定超参数。</p><h2 id="八、reinforce-怎样完成一次更新" tabindex="-1">八、REINFORCE 怎样完成一次更新 <a class="header-anchor" href="#八、reinforce-怎样完成一次更新" aria-label="Permalink to &quot;八、REINFORCE 怎样完成一次更新&quot;">​</a></h2><h3 id="_8-1-用当前策略采集完整回合" tabindex="-1">8.1 用当前策略采集完整回合 <a class="header-anchor" href="#_8-1-用当前策略采集完整回合" aria-label="Permalink to &quot;8.1 用当前策略采集完整回合&quot;">​</a></h3><p>每步保存状态、采样动作、动作对数概率和奖励，直到自然终止或按正确语义处理截断。</p><h3 id="_8-2-从后向前计算未来回报" tabindex="-1">8.2 从后向前计算未来回报 <a class="header-anchor" href="#_8-2-从后向前计算未来回报" aria-label="Permalink to &quot;8.2 从后向前计算未来回报&quot;">​</a></h3><p>利用递推 (G_t=R_{t+1}+\\gamma G_{t+1}) 计算每个时刻的未来回报，避免反复求和。</p><h3 id="_8-3-构造加权对数似然目标" tabindex="-1">8.3 构造加权对数似然目标 <a class="header-anchor" href="#_8-3-构造加权对数似然目标" aria-label="Permalink to &quot;8.3 构造加权对数似然目标&quot;">​</a></h3><p>若优化器执行梯度下降，可最小化：</p><p>$$ L(\\theta)=-\\frac{1}{N}\\sum_{i,t}G_t^{(i)}\\log\\pi_\\theta(A_t^{(i)}|S_t^{(i)}) $$</p><p>负号把最大化期望回报转换为常用最小化接口。</p><h3 id="_8-4-更新后重新采样" tabindex="-1">8.4 更新后重新采样 <a class="header-anchor" href="#_8-4-更新后重新采样" aria-label="Permalink to &quot;8.4 更新后重新采样&quot;">​</a></h3><p>基础 REINFORCE 属于 On-Policy（同策略）方法。参数改变后，旧轨迹不再来自新策略，不能像 DQN 回放数据那样无修正地长期复用。</p><p><img src="'+l+'" alt="REINFORCE 采样完整轨迹后计算未来回报并更新策略"></p><h2 id="九、基线为什么能降低方差" tabindex="-1">九、基线为什么能降低方差 <a class="header-anchor" href="#九、基线为什么能降低方差" aria-label="Permalink to &quot;九、基线为什么能降低方差&quot;">​</a></h2><h3 id="_9-1-绝对回报不说明相对表现" tabindex="-1">9.1 绝对回报不说明相对表现 <a class="header-anchor" href="#_9-1-绝对回报不说明相对表现" aria-label="Permalink to &quot;9.1 绝对回报不说明相对表现&quot;">​</a></h3><p>若所有轨迹奖励都为正，所有采样动作都被要求提高概率，更新主要依赖概率归一化间接竞争，噪声会很大。</p><h3 id="_9-2-减去与动作无关的基线不改变期望" tabindex="-1">9.2 减去与动作无关的基线不改变期望 <a class="header-anchor" href="#_9-2-减去与动作无关的基线不改变期望" aria-label="Permalink to &quot;9.2 减去与动作无关的基线不改变期望&quot;">​</a></h3><p>策略梯度可以写成：</p><p>$$ \\mathbb E[(G_t-b(S_t))\\nabla_\\theta\\log\\pi_\\theta(A_t|S_t)] $$</p><p>只要基线在给定状态下不依赖当前动作，其期望附加项为零。</p><h3 id="_9-3-状态价值是常用基线" tabindex="-1">9.3 状态价值是常用基线 <a class="header-anchor" href="#_9-3-状态价值是常用基线" aria-label="Permalink to &quot;9.3 状态价值是常用基线&quot;">​</a></h3><p>令 (b(S_t)\\approx V^\\pi(S_t))，权重就近似为 Advantage（优势）：当前动作结果相对该状态通常水平好多少。</p><h3 id="_9-4-基线减少方差但不消除采样噪声" tabindex="-1">9.4 基线减少方差但不消除采样噪声 <a class="header-anchor" href="#_9-4-基线减少方差但不消除采样噪声" aria-label="Permalink to &quot;9.4 基线减少方差但不消除采样噪声&quot;">​</a></h3><p>价值估计不准时，优势仍有误差。基线的职责是中心化与解释相对表现，不是把策略梯度变成确定性梯度。</p><p><img src="'+n+'" alt="状态基线把绝对回报转换为相对优势"></p><h2 id="十、回报标准化会改变什么" tabindex="-1">十、回报标准化会改变什么 <a class="header-anchor" href="#十、回报标准化会改变什么" aria-label="Permalink to &quot;十、回报标准化会改变什么&quot;">​</a></h2><h3 id="_10-1-批内中心化常用于稳定尺度" tabindex="-1">10.1 批内中心化常用于稳定尺度 <a class="header-anchor" href="#_10-1-批内中心化常用于稳定尺度" aria-label="Permalink to &quot;10.1 批内中心化常用于稳定尺度&quot;">​</a></h3><p>从一批回报减去均值、除以标准差，可避免不同批次梯度量级剧烈变化。这是工程归一化，不等同于理论上的状态价值基线。</p><h3 id="_10-2-小批次统计可能噪声很大" tabindex="-1">10.2 小批次统计可能噪声很大 <a class="header-anchor" href="#_10-2-小批次统计可能噪声很大" aria-label="Permalink to &quot;10.2 小批次统计可能噪声很大&quot;">​</a></h3><p>批次太小时，均值和标准差受个别轨迹主导。跨任务比较必须报告归一化方式，不能把其效果隐含在实现中。</p><h3 id="_10-3-奖励缩放会改变优化条件" tabindex="-1">10.3 奖励缩放会改变优化条件 <a class="header-anchor" href="#_10-3-奖励缩放会改变优化条件" aria-label="Permalink to &quot;10.3 奖励缩放会改变优化条件&quot;">​</a></h3><p>把所有奖励乘常数不改变最优策略的理想排序，却会改变梯度尺度、价值损失和学习率敏感性。训练配置应记录原始与变换后的奖励。</p><h2 id="十一、熵正则怎样维持探索" tabindex="-1">十一、熵正则怎样维持探索 <a class="header-anchor" href="#十一、熵正则怎样维持探索" aria-label="Permalink to &quot;十一、熵正则怎样维持探索&quot;">​</a></h2><h3 id="_11-1-策略可能过早变得确定" tabindex="-1">11.1 策略可能过早变得确定 <a class="header-anchor" href="#_11-1-策略可能过早变得确定" aria-label="Permalink to &quot;11.1 策略可能过早变得确定&quot;">​</a></h3><p>少量偶然成功就可能把某动作概率推高，其他动作随后很少被采样，智能体难以纠正早期误判。</p><h3 id="_11-2-entropy-bonus-熵奖励-鼓励分布不过度集中" tabindex="-1">11.2 Entropy Bonus（熵奖励）鼓励分布不过度集中 <a class="header-anchor" href="#_11-2-entropy-bonus-熵奖励-鼓励分布不过度集中" aria-label="Permalink to &quot;11.2 Entropy Bonus（熵奖励）鼓励分布不过度集中&quot;">​</a></h3><p>在目标中加入策略熵 (\\mathcal H(\\pi_\\theta(\\cdot|s)))，可以延缓概率塌缩，为不同动作保留采样机会。</p><h3 id="_11-3-熵系数不是越大越好" tabindex="-1">11.3 熵系数不是越大越好 <a class="header-anchor" href="#_11-3-熵系数不是越大越好" aria-label="Permalink to &quot;11.3 熵系数不是越大越好&quot;">​</a></h3><p>熵权重过大时，策略持续随机，回报无法提升；过小时又可能过早收敛。应同时记录策略熵、动作覆盖和评估回报。</p><h2 id="十二、连续动作策略有哪些陷阱" tabindex="-1">十二、连续动作策略有哪些陷阱 <a class="header-anchor" href="#十二、连续动作策略有哪些陷阱" aria-label="Permalink to &quot;十二、连续动作策略有哪些陷阱&quot;">​</a></h2><h3 id="_12-1-标准差决定探索尺度" tabindex="-1">12.1 标准差决定探索尺度 <a class="header-anchor" href="#_12-1-标准差决定探索尺度" aria-label="Permalink to &quot;12.1 标准差决定探索尺度&quot;">​</a></h3><p>均值决定主要动作，标准差决定采样范围。标准差塌缩会停止探索，持续过大又会带来抖动和越界动作。</p><h3 id="_12-2-多维动作相关性可能被忽略" tabindex="-1">12.2 多维动作相关性可能被忽略 <a class="header-anchor" href="#_12-2-多维动作相关性可能被忽略" aria-label="Permalink to &quot;12.2 多维动作相关性可能被忽略&quot;">​</a></h3><p>对转角和加速度使用独立高斯，相当于假设条件独立。真实驾驶中两者可能耦合，简单对角协方差策略表达能力有限。</p><h3 id="_12-3-动作单位和归一化必须一致" tabindex="-1">12.3 动作单位和归一化必须一致 <a class="header-anchor" href="#_12-3-动作单位和归一化必须一致" aria-label="Permalink to &quot;12.3 动作单位和归一化必须一致&quot;">​</a></h3><p>网络常输出归一化动作，再映射到物理范围。训练、评估和安全层若使用不同单位，概率与实际动作就会错位。</p><h2 id="十三、同策略数据为什么昂贵" tabindex="-1">十三、同策略数据为什么昂贵 <a class="header-anchor" href="#十三、同策略数据为什么昂贵" aria-label="Permalink to &quot;十三、同策略数据为什么昂贵&quot;">​</a></h2><h3 id="_13-1-参数更新会改变数据来源" tabindex="-1">13.1 参数更新会改变数据来源 <a class="header-anchor" href="#_13-1-参数更新会改变数据来源" aria-label="Permalink to &quot;13.1 参数更新会改变数据来源&quot;">​</a></h3><p>旧轨迹由 (\\pi_{\\theta_{old}}) 产生，新梯度目标对应 (\\pi_\\theta)。二者差异越大，直接复用旧动作对数概率产生的偏差越大。</p><h3 id="_13-2-基础-reinforce-通常每批只更新一次" tabindex="-1">13.2 基础 REINFORCE 通常每批只更新一次 <a class="header-anchor" href="#_13-2-基础-reinforce-通常每批只更新一次" aria-label="Permalink to &quot;13.2 基础 REINFORCE 通常每批只更新一次&quot;">​</a></h3><p>采集完整轨迹的成本很高，更新后却需要丢弃或谨慎处理旧数据，这使样本效率明显低于带回放的异策略价值方法。</p><h3 id="_13-3-重要性比率提供后续桥梁" tabindex="-1">13.3 重要性比率提供后续桥梁 <a class="header-anchor" href="#_13-3-重要性比率提供后续桥梁" aria-label="Permalink to &quot;13.3 重要性比率提供后续桥梁&quot;">​</a></h3><p>用新旧策略动作概率比率可以修正分布差异，但比率过大或过小时方差会爆炸。第 15 篇 PPO 将限制这一更新幅度。</p><h2 id="十四、自动驾驶应用应怎样限定" tabindex="-1">十四、自动驾驶应用应怎样限定 <a class="header-anchor" href="#十四、自动驾驶应用应怎样限定" aria-label="Permalink to &quot;十四、自动驾驶应用应怎样限定&quot;">​</a></h2><h3 id="_14-1-连续输出适合构造候选控制策略" tabindex="-1">14.1 连续输出适合构造候选控制策略 <a class="header-anchor" href="#_14-1-连续输出适合构造候选控制策略" aria-label="Permalink to &quot;14.1 连续输出适合构造候选控制策略&quot;">​</a></h3><p>策略可生成连续曲率、加速度或轨迹参数，避免离散动作分辨率限制，但应先在仿真与封闭场景验证。</p><h3 id="_14-2-概率探索不能直接进入公开道路" tabindex="-1">14.2 概率探索不能直接进入公开道路 <a class="header-anchor" href="#_14-2-概率探索不能直接进入公开道路" aria-label="Permalink to &quot;14.2 概率探索不能直接进入公开道路&quot;">​</a></h3><p>随机策略的探索动作必须经过动力学约束、规则检查和独立安全层。降低标准差只是减少随机性，不是安全证明。</p><h3 id="_14-3-奖励设计仍可能诱发投机行为" tabindex="-1">14.3 奖励设计仍可能诱发投机行为 <a class="header-anchor" href="#_14-3-奖励设计仍可能诱发投机行为" aria-label="Permalink to &quot;14.3 奖励设计仍可能诱发投机行为&quot;">​</a></h3><p>只奖励进度可能导致超速或过近跟车；碰撞惩罚也无法覆盖所有未见危险。需要独立约束指标和失败场景回放。</p><h3 id="_14-4-部署动作通常使用确定性代表值" tabindex="-1">14.4 部署动作通常使用确定性代表值 <a class="header-anchor" href="#_14-4-部署动作通常使用确定性代表值" aria-label="Permalink to &quot;14.4 部署动作通常使用确定性代表值&quot;">​</a></h3><p>评估或部署可使用分布均值或众数，但这与训练时随机策略不同。报告结果时必须说明动作选择方式。</p><p><img src="'+s+'" alt="连续策略输出仍需经过动作变换、约束和安全层"></p><h2 id="十五、一个最小实验怎样设计" tabindex="-1">十五、一个最小实验怎样设计 <a class="header-anchor" href="#十五、一个最小实验怎样设计" aria-label="Permalink to &quot;十五、一个最小实验怎样设计&quot;">​</a></h2><h3 id="_15-1-先从离散动作短回合开始" tabindex="-1">15.1 先从离散动作短回合开始 <a class="header-anchor" href="#_15-1-先从离散动作短回合开始" aria-label="Permalink to &quot;15.1 先从离散动作短回合开始&quot;">​</a></h3><p>使用 CartPole（倒立摆小车）等环境验证对数概率、未来回报、终止掩码与梯度符号，避免一开始同时处理连续分布和长时域。</p><h3 id="_15-2-对比无基线与有基线版本" tabindex="-1">15.2 对比无基线与有基线版本 <a class="header-anchor" href="#_15-2-对比无基线与有基线版本" aria-label="Permalink to &quot;15.2 对比无基线与有基线版本&quot;">​</a></h3><p>保持交互预算和随机种子一致，记录梯度范数、批次回报方差、学习曲线和策略熵，观察基线是否减少波动。</p><h3 id="_15-3-再测试连续动作参数化" tabindex="-1">15.3 再测试连续动作参数化 <a class="header-anchor" href="#_15-3-再测试连续动作参数化" aria-label="Permalink to &quot;15.3 再测试连续动作参数化&quot;">​</a></h3><p>检查采样动作范围、对数概率有限性、标准差变化和确定性评估。任何 NaN（非数值）都应追溯到分布参数或极端对数概率。</p><h2 id="十六、最常见的实现错误" tabindex="-1">十六、最常见的实现错误 <a class="header-anchor" href="#十六、最常见的实现错误" aria-label="Permalink to &quot;十六、最常见的实现错误&quot;">​</a></h2><h3 id="_16-1-对动作概率而不是对数概率加权" tabindex="-1">16.1 对动作概率而不是对数概率加权 <a class="header-anchor" href="#_16-1-对动作概率而不是对数概率加权" aria-label="Permalink to &quot;16.1 对动作概率而不是对数概率加权&quot;">​</a></h3><p>策略梯度使用 (\\nabla\\log\\pi)，不是简单用概率乘回报。成熟分布接口应直接返回稳定的 <code>log_prob</code>。</p><h3 id="_16-2-连续动作忘记合并维度" tabindex="-1">16.2 连续动作忘记合并维度 <a class="header-anchor" href="#_16-2-连续动作忘记合并维度" aria-label="Permalink to &quot;16.2 连续动作忘记合并维度&quot;">​</a></h3><p>多维独立分布通常为每个动作维度返回对数概率，需要沿动作维度求和，才能得到整项动作的联合对数概率。</p><h3 id="_16-3-把损失符号写反" tabindex="-1">16.3 把损失符号写反 <a class="header-anchor" href="#_16-3-把损失符号写反" aria-label="Permalink to &quot;16.3 把损失符号写反&quot;">​</a></h3><p>理论执行梯度上升，常见优化器执行梯度下降，因此损失需要负号。符号错会系统性降低好动作概率。</p><h3 id="_16-4-用评估均值动作采集训练数据" tabindex="-1">16.4 用评估均值动作采集训练数据 <a class="header-anchor" href="#_16-4-用评估均值动作采集训练数据" aria-label="Permalink to &quot;16.4 用评估均值动作采集训练数据&quot;">​</a></h3><p>训练轨迹必须来自声明的随机策略。若采集时偷偷取均值，而损失仍按随机分布计算，行为策略与记录概率不一致。</p><h2 id="十七、学到什么程度才算掌握" tabindex="-1">十七、学到什么程度才算掌握 <a class="header-anchor" href="#十七、学到什么程度才算掌握" aria-label="Permalink to &quot;十七、学到什么程度才算掌握&quot;">​</a></h2><h3 id="_17-1-能从轨迹概率推到梯度估计" tabindex="-1">17.1 能从轨迹概率推到梯度估计 <a class="header-anchor" href="#_17-1-能从轨迹概率推到梯度估计" aria-label="Permalink to &quot;17.1 能从轨迹概率推到梯度估计&quot;">​</a></h3><p>应能说明环境为何无需可微、对数导数技巧为何成立，以及最终梯度中为何只剩动作对数概率。</p><h3 id="_17-2-能解释回报、基线和优势的职责" tabindex="-1">17.2 能解释回报、基线和优势的职责 <a class="header-anchor" href="#_17-2-能解释回报、基线和优势的职责" aria-label="Permalink to &quot;17.2 能解释回报、基线和优势的职责&quot;">​</a></h3><p>未来回报提供样本评价，基线减少方差，二者之差表达相对优势。它们不能被混成一个含义模糊的“奖励”。</p><h3 id="_17-3-能区分训练策略和部署动作" tabindex="-1">17.3 能区分训练策略和部署动作 <a class="header-anchor" href="#_17-3-能区分训练策略和部署动作" aria-label="Permalink to &quot;17.3 能区分训练策略和部署动作&quot;">​</a></h3><p>随机策略用于探索和梯度估计，确定性均值常用于评估；两种协议必须分别记录。</p><h3 id="_17-4-能准备进入-actor-critic" tabindex="-1">17.4 能准备进入 Actor-Critic <a class="header-anchor" href="#_17-4-能准备进入-actor-critic" aria-label="Permalink to &quot;17.4 能准备进入 Actor-Critic&quot;">​</a></h3><p>下一篇将用 Critic（评论家）学习状态价值，以一步或多步 TD（时序差分）优势替代完整蒙特卡洛回报，让演员不必每次等到回合结束。</p><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><p><a href="https://github.com/datawhalechina/easy-rl/blob/master/docs/chapter4/chapter4.md" target="_blank" rel="noreferrer">《蘑菇书 EasyRL》第四章策略梯度</a></p><p><a href="https://spinningup.openai.com/en/latest/spinningup/rl_intro3.html" target="_blank" rel="noreferrer">OpenAI Spinning Up 策略优化入门</a></p><p><a href="http://incompleteideas.net/book/the-book-2nd.html" target="_blank" rel="noreferrer">Sutton 与 Barto《Reinforcement Learning: An Introduction》第二版第十三章</a></p><p><a href="https://link.springer.com/article/10.1007/BF00992696" target="_blank" rel="noreferrer">Williams《Simple Statistical Gradient-Following Algorithms for Connectionist Reinforcement Learning》</a></p>',154)])])}const k=e(d,[["render",c]]);export{f as __pageData,k as default};
